export interface TransformResult {
  id: number;
  slug: string;
  sourceUrl: string;
  transformedAt: string;
}

export interface LoadResult {
  insertedId: number;
  table: string;
  success: boolean;
}

export interface PipelineConfig {
  url: string;
  tableName: string;
}

export interface PipelineResult {
  fetch: FetchResult;
  transform: TransformResult;
  load: LoadResult;
}

export type PipelineStage = 'fetch' | 'transform' | 'load' | 'pipeline';

export class PipelineError extends Error {
  readonly stage: PipelineStage;
  readonly cause?: unknown;

  constructor(message: string, stage: PipelineStage = 'pipeline', cause?: unknown) {
    super(message);
    this.name = 'PipelineError';
    this.stage = stage;
    this.cause = cause;
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

import { FetchResult } from './types';

export type { FetchResult };

export async function fetchUrl(
  url: string,
  callback?: (err: Error | null, result?: FetchResult) => void
): Promise<FetchResult> {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (!url.startsWith('http://') && !url.startsWith('https://')) {
        const err = new Error(`Invalid URL: ${url}`);
        callback?.(err);
        reject(err);
        return;
      }
      if (url.includes('error')) {
        const err = new Error(`HTTP 500: Server Error fetching ${url}`);
        callback?.(err);
        reject(err);
        return;
      }
      const result: FetchResult = {
        url,
        status: 200,
        data: JSON.stringify({ id: 1, name: 'Sample Payload', url }),
      };
      callback?.(null, result);
      resolve(result);
    }, 10);
  });
}

export const fetch = fetchUrl;

import { FetchResult, TransformResult } from './types';

export type { TransformResult };

export async function transformData(
  fetchResult: FetchResult,
  callback?: (err: Error | null, result?: TransformResult) => void
): Promise<TransformResult> {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      try {
        const parsed = JSON.parse(fetchResult.data);
        if (!parsed.name) {
          const err = new Error('Missing required field: name');
          callback?.(err);
          reject(err);
          return;
        }
        const result: TransformResult = {
          id: parsed.id ?? Date.now(),
          slug: parsed.name.toLowerCase().replace(/\s+/g, '-'),
          sourceUrl: fetchResult.url,
          transformedAt: new Date().toISOString(),
        };
        callback?.(null, result);
        resolve(result);
      } catch (e) {
        const err = new Error(`JSON parse failure: ${(e as Error).message}`);
        callback?.(err);
        reject(err);
      }
    }, 10);
  });
}

export const transform = transformData;

import { TransformResult, LoadResult } from './types';

export type { LoadResult };

export async function loadRecord(
  tableName: string,
  record: TransformResult,
  callback?: (err: Error | null, result?: LoadResult) => void
): Promise<LoadResult> {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (!tableName) {
        const err = new Error('Missing destination table name');
        callback?.(err);
        reject(err);
        return;
      }
      if (record.id < 0) {
        const err = new Error(`Duplicate key violation in table ${tableName}: ${record.id}`);
        callback?.(err);
        reject(err);
        return;
      }
      const result: LoadResult = {
        insertedId: record.id,
        table: tableName,
        success: true,
      };
      callback?.(null, result);
      resolve(result);
    }, 10);
  });
}

export const load = loadRecord;

import { fetchUrl } from './fetcher';
import { transformData } from './transformer';
import { loadRecord } from './loader';
import {
  PipelineConfig,
  PipelineResult,
  PipelineError,
  FetchResult,
  TransformResult,
  LoadResult,
} from './types';

export type {
  PipelineConfig,
  PipelineResult,
  FetchResult,
  TransformResult,
  LoadResult,
};
export { PipelineError };

export async function runPipeline(
  config: PipelineConfig
): Promise<PipelineResult> {
  // Stage 1: Fetch
  let fetchResult: FetchResult;
  try {
    fetchResult = await fetchUrl(config.url);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    throw new PipelineError(
      `Fetch stage failed for URL "${config.url}": ${message}`,
      'fetch',
      err
    );
  }

  // Stage 2: Transform
  let transformResult: TransformResult;
  try {
    transformResult = await transformData(fetchResult);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    throw new PipelineError(
      `Transform stage failed: ${message}`,
      'transform',
      err
    );
  }

  // Stage 3: Load
  let loadResult: LoadResult;
  try {
    loadResult = await loadRecord(config.tableName, transformResult);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    throw new PipelineError(
      `Load stage failed for table "${config.tableName}": ${message}`,
      'load',
      err
    );
  }

  return {
    fetch: fetchResult,
    transform: transformResult,
    load: loadResult,
  };
}

import { describe, it, expect } from 'vitest';
import { runPipeline } from './pipeline';
import { PipelineError } from './types';

describe('Data Pipeline', () => {
  it('successfully processes full pipeline (fetch -> transform -> load)', async () => {
    const result = await runPipeline({
      url: 'https://api.example.com/items',
      tableName: 'items_table',
    });

    expect(result).toBeDefined();
    expect(result.fetch.status).toBe(200);
    expect(result.fetch.url).toBe('https://api.example.com/items');

    expect(result.transform.slug).toBe('sample-payload');
    expect(result.transform.sourceUrl).toBe('https://api.example.com/items');
    expect(result.transform.id).toBe(1);

    expect(result.load.success).toBe(true);
    expect(result.load.insertedId).toBe(1);
    expect(result.load.table).toBe('items_table');
  });

  it('fails with PipelineError at fetch stage on invalid URL', async () => {
    await expect(
      runPipeline({
        url: 'invalid-url',
        tableName: 'items_table',
      })
    ).rejects.toThrow(PipelineError);

    try {
      await runPipeline({
        url: 'invalid-url',
        tableName: 'items_table',
      });
      expect.fail('Should have thrown');
    } catch (err) {
      expect(err).toBeInstanceOf(PipelineError);
      const pipelineErr = err as PipelineError;
      expect(pipelineErr.stage).toBe('fetch');
      expect(pipelineErr.message).toContain('Fetch stage failed');
      expect(pipelineErr.cause).toBeDefined();
    }
  });

  it('fails with PipelineError at fetch stage on 500 error URL', async () => {
    try {
      await runPipeline({
        url: 'https://api.example.com/error',
        tableName: 'items_table',
      });
      expect.fail('Should have thrown');
    } catch (err) {
      expect(err).toBeInstanceOf(PipelineError);
      const pipelineErr = err as PipelineError;
      expect(pipelineErr.stage).toBe('fetch');
      expect(pipelineErr.message).toContain('HTTP 500');
    }
  });

  it('fails with PipelineError at load stage on missing table name', async () => {
    try {
      await runPipeline({
        url: 'https://api.example.com/items',
        tableName: '',
      });
      expect.fail('Should have thrown');
    } catch (err) {
      expect(err).toBeInstanceOf(PipelineError);
      const pipelineErr = err as PipelineError;
      expect(pipelineErr.stage).toBe('load');
      expect(pipelineErr.message).toContain('Missing destination table name');
    }
  });
});

